// Editorial structure for the documentation site. Native examples stay in data.json.
const icon=name=>`<span class="symbol" aria-hidden="true">${name}</span>`;
const a=(href,label)=>`<a class="text-link" href="${href}">${label}${icon('arrow_forward')}</a>`;
const p=text=>`<p>${text}</p>`;
const list=items=>`<ul class="doc-list">${items.map(text=>`<li>${text}</li>`).join('')}</ul>`;
const table=(head,rows)=>`<div class="table-scroll"><table class="spec-table"><thead><tr>${head.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const s=(id,title,html)=>({id,title,html});
const page=(title,intro,sections,art)=>({title,intro,sections,art});

